mapper.select:
select from `ry_rental`.`ry_rental_brand` b inner join ( select relation.brand_id, group_concat( concat_ws(' / ', parent_class.class_name, pc.class_name) order by relation.class_id separator '，' ) as class_name from `ry_rental`.`ry_rental_brand_class` relation inner join `ry_rental`.`ry_rental_product_class` pc on pc.class_id = relation.class_id and pc.class_level = 2 and pc.is_delete = 0 inner join `ry_rental`.`ry_rental_product_class` parent_class on parent_class.class_id = pc.parent_id and parent_class.class_level = 1 and parent_class.is_delete = 0 where relation.is_delete = 0 group by relation.brand_id ) relation on relation.brand_id = b.brand_id where b.is_delete = 0 and b.brand_name like concat('%', #{brandName}, '%') and b.status = #{status}
and exists ( select 1 from `ry_rental`.`ry_rental_brand_class` filter_relation where filter_relation.brand_id = b.brand_id and filter_relation.class_id = #{classId} and filter_relation.is_delete = 0 )
order by b.create_time desc, b.brand_id desc

mapper.insert:
insert into `ry_rental`.`ry_rental_brand`(
    brand_name, sort_no, status, is_delete, create_by, create_time, remark
) values (
    #{brandName}, coalesce(#{sortNo}, 0), #{status}, 0, #{createBy}, sysdate(), #{remark}
)
